function power(base, exponent = 2) {
  return base ** exponent;
}

function resetScores(scores) {
  for (let i = 0; i < scores.length; i++) {
    scores[i] = 0;
  }
}

function replaceScores(scores) {
  scores = [100];
  console.log(`inside: ${scores.join(", ")}`);
}

