console.log(`power(2, 10) = ${power(2, 10)}`);
console.log(`power(3, 3, 99) = ${power(3, 3, 99)}`);

const roundScores = [70, 85, 90];
resetScores(roundScores);
replaceScores(roundScores);
console.log(`outside: ${roundScores.join(", ")}`);

steps.body:
A function can have several `return` statements. The first one that runs ends the call. Use that for guard clauses: handle the special cases at the top and return early, so the main logic below stays flat instead of nested in `else` blocks.

```javascript
function isAdult(age) {
  if (age < 0) {
    return false; // guard: bad input
  }
  return age >= 18;
}
```

Name functions that answer yes or no with `is` or `has` (`isPrime`, `hasDiscount`) and make them return `true` or `false`. Then calls read like questions: `if (isPrime(n)) { ... }`.

Small functions combine well. A helper does one job, and a bigger function calls it in a loop. Each part is short and easy to test on its own.

example.code:
function isPrime(n) {
  if (n < 2) {
    return false;
  }
  for (let d = 2; d * d <= n; d++) {
    if (n % d === 0) {
      return false;
    }
  }
  return true;
}

function primesUpTo(limit) {
  const primes = [];
  for (let n = 2; n <= limit; n++) {
    if (isPrime(n)) {
      primes.push(n);
    }
  }
  return primes;
}

console.log(`Primes up to 30: ${primesUpTo(30).join(" ")}`);
console.log(`isPrime(1): ${isPrime(1)}`);
console.log(`isPrime(97): ${isPrime(97)}`);

