practice.solution:
function isLeapYear(year) {
  if (year % 400 === 0) {
    return true;
  }
  if (year % 100 === 0) {
    return false;
  }
  return year % 4 === 0;
}

function leapYearsBetween(start, end) {
  const years = [];
  for (let year = start; year <= end; year++) {
    if (isLeapYear(year)) {
      years.push(year);
    }
  }
  return years;
}

console.log(`Leap years 1896 to 1912: ${leapYearsBetween(1896, 1912).join(" ")}`);
console.log(`isLeapYear(1900): ${isLeapYear(1900)}`);
console.log(`isLeapYear(2000): ${isLeapYear(2000)}`);
